import React, { useState, useRef, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
  Box, Typography, Paper, TextField, InputAdornment, IconButton, Chip,
  Avatar, Stack, CircularProgress,
} from '@mui/material';
import SendIcon from '@mui/icons-material/Send';
import SmartToyIcon from '@mui/icons-material/SmartToy';
import axiosInstance from '../../api/axiosConfig';
import { formatPersianNumber, toPersianDigits } from '../../utils/numberUtils';
import { toJalali } from '../../utils/dateUtils';

/**
 * دستیار HR — کاملاً آفلاین و سبک (Rule-based).
 * داده‌ها از گزارشات موجود سازمان خوانده می‌شوند (بدون مدل زبانی، بدون اینترنت).
 */
const HRAssistant = () => {
  const [messages, setMessages] = useState([
    {
      from: 'bot',
      text: 'سلام! 👋 من دستیار منابع انسانی هستم. درباره پرسنل، دپارتمان‌ها، حقوق، تولدها و قراردادها از من بپرسید.',
    },
  ]);
  const [input, setInput] = useState('');
  const [typing, setTyping] = useState(false);
  const endRef = useRef(null);

  // Data fetched once (lightweight, parallel, cached by React Query)
  const { data: byDept } = useQuery({ queryKey: ['assist-dept'], queryFn: () => axiosInstance.get('/reports/employees-by-department/').then(r => r.data) });
  const { data: byGender } = useQuery({ queryKey: ['assist-gender'], queryFn: () => axiosInstance.get('/reports/employees-by-gender/').then(r => r.data) });
  const { data: byLocation } = useQuery({ queryKey: ['assist-loc'], queryFn: () => axiosInstance.get('/reports/employees-by-location/').then(r => r.data) });
  const { data: byJobTitle } = useQuery({ queryKey: ['assist-job'], queryFn: () => axiosInstance.get('/reports/employees-by-job-title/').then(r => r.data) });
  const { data: turnover } = useQuery({ queryKey: ['assist-turnover'], queryFn: () => axiosInstance.get('/reports/turnover-rate/').then(r => r.data) });
  const { data: avgAge } = useQuery({ queryKey: ['assist-age'], queryFn: () => axiosInstance.get('/reports/average-age-experience/').then(r => r.data) });
  const { data: birthdays } = useQuery({ queryKey: ['assist-birthdays'], queryFn: () => axiosInstance.get('/reports/upcoming-birthdays/').then(r => r.data) });
  const { data: contracts } = useQuery({ queryKey: ['assist-contracts'], queryFn: () => axiosInstance.get('/reports/contracts-expiring/').then(r => r.data) });
  const { data: corrSummary } = useQuery({ queryKey: ['assist-corr'], queryFn: () => axiosInstance.get('/reports/correspondences-summary/').then(r => r.data) });
  const { data: salaryBenefit } = useQuery({ queryKey: ['assist-salary'], queryFn: () => axiosInstance.get('/reports/salary-benefits-summary/').then(r => r.data) });
  const { data: employees } = useQuery({ queryKey: ['assist-employees'], queryFn: () => axiosInstance.get('/employees/', { params: { page_size: 500 } }).then(r => r.data.results || r.data) });

  const data = {
    totalEmployees: (byGender || []).reduce((sum, g) => sum + (g.count || 0), 0),
    avgAgeOverall: (() => {
      const vals = (avgAge || []).map(a => a.avg_age).filter(v => v != null && !isNaN(v));
      return vals.length ? Math.round(vals.reduce((s, v) => s + Number(v), 0) / vals.length) : 0;
    })(),
    byDept, byLocation, byJobTitle, byGender, turnover, birthdays, contracts, corrSummary, salaryBenefit, employees,
  };

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, typing]);

  const normalize = (s) => (s || '').toLowerCase().replace(/[‌\s]+/g, ' ').trim();

  const answerQuestion = (raw) => {
    const q = normalize(raw);

    const findTopDept = () => {
      const list = data.byDept || [];
      return list.length ? [...list].sort((a, b) => b.count - a.count)[0] : null;
    };
    const findTopLocation = () => {
      const list = data.byLocation || [];
      return list.length ? [...list].sort((a, b) => b.count - a.count)[0] : null;
    };
    const findTopJobTitle = () => {
      const list = data.byJobTitle || [];
      return list.length ? [...list].sort((a, b) => b.count - a.count)[0] : null;
    };

    const total = data.totalEmployees || 0;

    if (/(چند|تعداد|چه تعداد).*(پرسنل|نفر|کارمند|کارکن)/.test(q) || /پرسنل.*(چند|تعداد)/.test(q)) {
      return `در حال حاضر ${formatPersianNumber(total)} پرسنل فعال در سازمان ثبت شده است.`;
    }
    if (/(بخش|دپارتمان|واحد)/.test(q)) {
      const top = findTopDept();
      if (/(بیشترین|بزرگ‌ترین|بیشتر)/.test(q) && top) return `بزرگ‌ترین دپارتمان «${top.name}» با ${formatPersianNumber(top.count)} نفر است.`;
      if (/[?؟]|چند|تعداد/.test(q) && top) return `دپارتمان «${top.name}» با ${formatPersianNumber(top.count)} نفر، بیشترین پرسنل را دارد.`;
      if (data.byDept && data.byDept.length) {
        const list = data.byDept.map(d => `${d.name} (${formatPersianNumber(d.count)} نفر)`).join('، ');
        return `توزیع پرسنل در دپارتمان‌ها: ${list}`;
      }
    }
    if (/(جنسیت|زن|مرد|خانم|آقا)/.test(q)) {
      const g = data.byGender || [];
      if (g.length) {
        const parts = g.map(x => `${x.gender}: ${formatPersianNumber(x.count)} نفر (${toPersianDigits(x.percent ?? 0)}٪)`).join('، ');
        return `ترکیب جنسیتی پرسنل: ${parts}`;
      }
    }
    if (/(خروج|ترک خدمت|اخراج|بازنشست)/.test(q)) {
      const t = data.turnover || {};
      return `نرخ ترک خدمت ${formatPersianNumber(t.rate ?? 0)}٪ است (${formatPersianNumber(t.terminated_count ?? 0)} خروج در این سال).`;
    }
    if (/(میانگین.*سن|سن.*میانگین|سن)/.test(q)) {
      return `میانگین سن پرسنل ${formatPersianNumber(data.avgAgeOverall ?? 0)} سال است.`;
    }
    if (/(تولد|متولد)/.test(q)) {
      // سؤال درباره تولد یک شخص خاص: نام فرد را پیدا کن
      const empList = (data.employees || []);
      for (const emp of empList) {
        const fn = normalize(emp.first_name || '');
        const ln = normalize(emp.last_name || '');
        if ((fn && q.includes(fn)) || (ln && q.includes(ln))) {
          if (emp.birth_date) {
            return `تاریخ تولد ${emp.full_name}: ${toJalali(emp.birth_date)} است.`;
          }
          return `تاریخ تولد ${emp.full_name} ثبت نشده است.`;
        }
      }
      // اگر نام خاصی نیامد، تولدهای ۷ روز آینده را نشان بده
      const b = data.birthdays || [];
      if (!b.length) return 'در ۷ روز آینده تولدی ثبت نشده است.';
      const list = b.map(x => `${x.full_name} (${x.is_today ? 'امروز' : `${toPersianDigits(x.days_until)} روز دیگر`})`).join('، ');
      return `تولدهای ۷ روز آینده: ${list}`;
    }
    if (/(قرارداد|انقضا|پایان قرارداد)/.test(q)) {
      const c = data.contracts || [];
      if (!c.length) return 'در ۹۰ روز آینده قراردادی منقضی نمی‌شود.';
      const list = c.slice(0, 5).map(x => x.full_name).join('، ');
      return `${formatPersianNumber(c.length)} قرارداد در شرف انقضا هستند، از جمله: ${list}`;
    }
    if (/(محل استقرار|شعبه|محل کار|مکان)/.test(q)) {
      const top = findTopLocation();
      if (top) return `محل استقرار «${top.name}» با ${formatPersianNumber(top.count)} نفر، بزرگ‌ترین شعبه است.`;
    }
    if (/(عنوان شغلی|سمت|شغل)/.test(q)) {
      const top = findTopJobTitle();
      if (top) return `عنوان شغلی «${top.name}» با ${formatPersianNumber(top.count)} نفر، رایج‌ترین سمت است.`;
    }
    if (/(حقوق|مزایا|پرداخت|کسور)/.test(q)) {
      const sb = data.salaryBenefit || {};
      return `جمع حقوق پرداختی ${formatPersianNumber(sb.total_salaries ?? 0)} ریال و جمع کسورات ${formatPersianNumber(sb.total_deductions ?? 0)} ریال است.`;
    }
    if (/(مکاتب|نامه|ابلاغ|فرم)/.test(q)) {
      const c = data.corrSummary || {};
      return `در سیستم: ${formatPersianNumber(c.incoming_letters ?? 0)} نامه وارده، ${formatPersianNumber(c.outgoing_letters ?? 0)} نامه صادره، ${formatPersianNumber(c.announcements ?? 0)} ابلاغ و ${formatPersianNumber(c.forms ?? 0)} فرم ثبت شده است.`;
    }
    if (/(سلام|درود|هی)/.test(q)) {
      return 'سلام! چطور می‌توانم کمکتان کنم؟ درباره پرسنل، دپارتمان‌ها، حقوق، تولدها و قراردادها می‌توانید بپرسید.';
    }
    if (/(ممنون|تشکر|مرسی|سپاس)/.test(q)) {
      return 'خواهش می‌کنم! اگر سؤال دیگری دارید در خدمتم. 😊';
    }
    return 'سؤال شما را متوجه نشدم. می‌توانید درباره «تعداد پرسنل»، «نرخ خروج»، «تولدهای ۷ روز آینده»، «قراردادها»، «حقوق و مزایا» و «مکاتبات» بپرسید.';
  };

  const send = (text) => {
    const question = text || input.trim();
    if (!question) return;
    setMessages(prev => [...prev, { from: 'user', text: question }]);
    setInput('');
    setTyping(true);
    setTimeout(() => {
      setMessages(prev => [...prev, { from: 'bot', text: answerQuestion(question) }]);
      setTyping(false);
    }, 300);
  };

  const suggestions = [
    'تعداد پرسنل چقدر است؟',
    'نرخ خروج چقدره؟',
    'تولدهای ۷ روز آینده کیان؟',
    'کدوم دپارتمان بزرگ‌ترینه؟',
    'وضعیت قراردادها چطوره؟',
  ];

  return (
    <Paper sx={{
      overflow: 'hidden',
      maxWidth: 700,
      width: '100%',
      background: 'linear-gradient(135deg, rgba(99,102,241,0.08), rgba(236,72,153,0.04))',
      border: '1px solid rgba(99,102,241,0.2)',
      backdropFilter: 'blur(18px)', WebkitBackdropFilter: 'blur(18px)',
      borderRadius: 3,
    }}>
      {/* Header */}
      <Box sx={{
        px: 2.5, py: 1.5,
        background: 'linear-gradient(135deg, rgba(99,102,241,0.14), rgba(236,72,153,0.08))',
        borderBottom: '1px solid rgba(99,102,241,0.16)',
        display: 'flex', alignItems: 'center', gap: 1.5,
      }}>
        <Avatar sx={{ width: 40, height: 40, background: 'linear-gradient(135deg, #6366f1, #ec4899)', boxShadow: '0 3px 12px rgba(99,102,241,0.4)' }}>
          <SmartToyIcon sx={{ color: '#fff', fontSize: 22 }} />
        </Avatar>
        <Box>
          <Typography variant="subtitle1" fontWeight={700}>دستیار منابع انسانی</Typography>
          <Typography variant="caption" color="textSecondary">پاسخ فوری و آفلاین از داده‌های سازمان</Typography>
        </Box>
      </Box>

      {/* Messages */}
      <Box sx={{ p: 2, minHeight: 280, maxHeight: 45 + 'vh', overflowY: 'auto' }}>
        <Stack spacing={1.5}>
          {messages.map((m, i) => (
            <Box key={i} sx={{ display: 'flex', justifyContent: m.from === 'user' ? 'flex-start' : 'flex-end' }}>
              <Paper sx={{
                px: 1.5, py: 1, maxWidth: '80%',
                background: m.from === 'user'
                  ? 'linear-gradient(135deg, rgba(99,102,241,0.9), rgba(139,92,246,0.9))'
                  : 'rgba(255,255,255,0.65)',
                color: m.from === 'user' ? '#fff' : 'text.primary',
                borderRadius: '14px 14px 4px 14px',
                border: m.from === 'user' ? 'none' : '1px solid rgba(99,102,241,0.16)',
              }}>
                <Typography variant="body2">{m.text}</Typography>
              </Paper>
            </Box>
          ))}
          {typing && (
            <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
              <Paper sx={{ px: 1.5, py: 1, background: 'rgba(255,255,255,0.65)', borderRadius: '14px 14px 4px 14px' }}>
                <Box sx={{ display: 'flex', gap: 0.5 }}>
                  <CircularProgress size={12} /><CircularProgress size={12} /><CircularProgress size={12} />
                </Box>
              </Paper>
            </Box>
          )}
          <div ref={endRef} />
        </Stack>
      </Box>

      {/* Suggestions */}
      <Box sx={{ px: 2, pb: 1, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
        {suggestions.map(s => (
          <Chip key={s} label={s} size="small" variant="outlined" clickable onClick={() => send(s)}
            sx={{ borderColor: 'rgba(99,102,241,0.35)', color: '#6366f1' }} />
        ))}
      </Box>

      {/* Input */}
      <Box sx={{ p: 2, pt: 1, borderTop: '1px solid rgba(99,102,241,0.12)' }}>
        <TextField
          fullWidth
          size="small"
          placeholder="سؤال خود را بنویسید..."
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => { if (e.key === 'Enter') send(); }}
          InputProps={{
            endAdornment: (
              <InputAdornment position="end">
                <IconButton size="small" color="primary" onClick={() => send()}>
                  <SendIcon fontSize="small" />
                </IconButton>
              </InputAdornment>
            ),
          }}
        />
      </Box>
    </Paper>
  );
};

export default HRAssistant;
